#pragma once
#include "api/EngineTypes.hpp"
#include <array>
#include <limits>
namespace player2 {
// Prepared on the worker. Only external inputs are journaled: compiled Cue/Event/
// Performance actions are regenerated by the one Runtime during replay.
class CommandJournal {
public:
    struct Record { api::EngineCommand command; api::EngineStatus result{}; std::int64_t frame{}; std::uint64_t epoch{};
        std::uint32_t actionsBegin{},actionsEnd{}; };
    static constexpr std::size_t capacity=8192;
    std::array<Record,capacity> records{};
    std::array<std::int64_t,capacity> epochEnds{};
    std::size_t size{},cursor{};
    std::uint64_t epoch{};
    bool complete{true};
    void stopped(std::int64_t frame,bool rebuilding) noexcept {
        if(epoch<epochEnds.size()) { if(!rebuilding) epochEnds[epoch]=frame; }
        else complete=false;
        if(epoch<std::numeric_limits<std::uint64_t>::max()) ++epoch; else complete=false;
    }
    void append(const api::EngineCommand& command,api::EngineStatus result,std::int64_t frame,std::uint64_t atEpoch,
        std::uint32_t actionsBegin=0,std::uint32_t actionsEnd=0) noexcept {
        // New input after a backward seek creates one timeline branch. Retain the
        // verified prefix, rather than later replaying obsolete control decisions.
        size=cursor;
        if(size==records.size()) { complete=false; return; }
        records[size++]={command,result,frame,atEpoch,actionsBegin,actionsEnd}; cursor=size;
    }
    bool withinBudget(std::uint64_t frames,std::uint64_t maximum) const noexcept {
        if(!complete || epoch>=epochEnds.size() || frames>maximum) return false;
        for(std::uint64_t n=0;n<epoch;++n) {
            const auto count=static_cast<std::uint64_t>(epochEnds[n]);
            if(count>maximum-frames) return false;
            frames+=count;
        }
        return true;
    }
    void rewind() noexcept { cursor=0; epoch=0; }
};
}
